void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
    int syscall_nr = regs->ax;
    struct syscall_metadata *metadata;

    if (syscall_nr < 0 || syscall_nr >= MAX_SYSCALL_NR)
        return;

    metadata = get_syscall_metadata(syscall_nr);
    if (!metadata || !metadata->enabled)
        return;

    if (!(metadata->event_mask & PERF_EVENT_EXIT))
        return;

    struct trace_buffer *buffer = allocate_trace_buffer();
    if (!buffer)
        return;

    buffer->syscall_nr = syscall_nr;
    buffer->return_value = ret;

    submit_trace_buffer(buffer);
}

void syscall_exit_trace(void *ignore, struct pt_regs *regs, long ret) {
    int syscall_num = regs->ax;
    struct syscall_metadata *metadata = get_syscall_metadata(syscall_num);

    if (!metadata || !metadata->enabled) {
        return;
    }

    struct syscall_event *event = metadata->exit_event;

    if (!event) {
        return;
    }

    struct trace_buffer *buffer = trace_buffer_alloc();
    if (!buffer) {
        return;
    }

    buffer->syscall_number = syscall_num;
    buffer->return_value = ret;

    trace_buffer_submit(buffer);
}

void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret) {
    int syscall_num = regs->syscall;

    if (syscall_num < 0 || syscall_num >= __NR_syscall_max)
        return;

    struct syscall_metadata *metadata = get_syscall_metadata(syscall_num);
    if (!metadata || !metadata->enable_perf)
        return;

    if (!metadata->exit_event)
        return;

    char buffer[PERF_BUFFER_SIZE];
    int event_id = metadata->exit_event;

    buffer[0] = (char)syscall_num;
    *(long *)(buffer + 1) = ret;

    submit_perf_buffer(buffer, event_id, PERF_BUFFER_SIZE);
}

#include <linux/tracepoint.h>
#include <linux/uaccess.h>

void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
    int syscallnr = (int)regs->ax;
    struct syscall_metadata *entry;

    if (syscallnr < 0 || syscallnr >= __NR_syscall_max)
        return;

    entry = &syscall_table[syscallnr];
    if (!entry->exit_event)
        return;

    if (!tracepoint_get_struct_size(entry->exit_event))
        return;

    if (trace_buffer_lock_reserve(entry->exit_event, TRACE_BUFFER_SIZE))
        return;

    struct trace_buffer *buffer = trace_buffer_get();
    if (!buffer)
        return;

    buffer->syscallnr = syscallnr;
    buffer->ret = ret;

    trace_buffer_submit(buffer);
}
